class Solution {
public:
    int countGoodRectangles(vector<vector<int>>& rectangles) {
        int maxLen = 0;
        for (const auto& r : rectangles) {
            int side = min(r[0], r[1]);
            if (side > maxLen) {
                maxLen = side;
            }
        }
        int count = 0;
        for (const auto& r : rectangles) {
            if (min(r[0], r[1]) == maxLen) {
                ++count;
            }
        }
        return count;
    }
};
